/**
 * A filter field built on BaseTypeahead's `menu`. Typing lists the fields
 * with a heading and a key hint around the list. Picking a field switches the
 * same menu to a dialog that edits its value; a filter's button reopens that
 * dialog, and Escape returns focus to the button.
 */
function BaseTypeaheadMenu() {
  const fieldRef = useRef(null);
  const typeahead = useRef(null);
  const [filters, setFilters] = useState([]);
  const [editing, setEditing] = useState(null);
  const [draft, setDraft] = useState('');
  const edit = filter => {
    setEditing(filter);
    setDraft(filter.value);
    typeahead.current?.open();
  };
  const menu = editing == null ? {
    role: 'listbox',
    render: ({
      listbox,
      query
    }) => <>
              <Text type="supporting" color="secondary" xstyle={styles.menuNote}>
                {query === '' ? 'Filter by' : `Fields matching “${query}”`}
              </Text>
              {listbox}
              <Text type="supporting" color="secondary" xstyle={styles.menuNote}>
                Arrow keys move, Enter picks
              </Text>
            </>
  } : {
    role: 'dialog',
    label: `${editing.field.label} filter`,
    render: ({
      close
    }) => <VStack gap={3} xstyle={styles.editor}>
              <RadioList label={editing.field.label} value={draft} onChange={setDraft}>
                {editing.field.values.map(value => <RadioListItem key={value} label={value} value={value} />)}
              </RadioList>
              <HStack gap={2} hAlign="end">
                <Button label="Cancel" variant="secondary" onClick={close} />
                <Button label="Apply" variant="primary" onClick={() => {
          const next = {
            field: editing.field,
            value: draft
          };
          setFilters(current => [...current.filter(f => f.field.id !== next.field.id), next]);
          close();
        }} />
              </HStack>
            </VStack>
  };
  return <VStack gap={3} xstyle={styles.root}>
      <HStack ref={fieldRef} gap={2} vAlign="center" xstyle={styles.field}>
        <Icon icon={FunnelIcon} size="sm" color="secondary" />
        <BaseTypeahead aria-label="Add a filter" searchSource={source} value={null} onChange={field => {
        if (field != null) {
          // A field that already has a filter opens on its applied value.
          edit(filters.find(filter => filter.field.id === field.id) ?? {
            field,
            value: field.values[0]
          });
        }
      }} onOpenChange={isOpen => {
        if (!isOpen) {
          setEditing(null);
        }
      }} handleRef={typeahead} menu={menu} anchorRef={fieldRef} placeholder="Add a filter…" hasEntriesOnFocus debounceMs={0} />
      </HStack>
      <HStack gap={2} wrap="wrap">
        {filters.length === 0 ? <Text type="supporting" color="secondary">
            No filters
          </Text> : filters.map(filter => <Button key={filter.field.id} label={`${filter.field.label}: ${filter.value}`} variant="secondary" size="sm" onClick={() => edit(filter)} />)}
      </HStack>
    </VStack>;
}

export default function BaseTypeaheadMenuDemo() {
  return (
    <div
      data-astryx-theme="neutral"
      data-theme="light"
      style={{colorScheme: 'light', display: 'contents'}}>
      <BaseTypeaheadMenu />
    </div>
  );
}
